def safe_state(available, alloc, need):
    n = len(alloc)
    work = available[:]
    finish = [False]*n
    while True:
        found = False
        for i in range(n):
            if not finish[i] and all(need[i][j] <= work[j] for j in range(len(work))):
                for j in range(len(work)):
                    work[j] += alloc[i][j]
                finish[i] = True
                found = True
        if not found:
            break
    return all(finish)

# Example data from the exam question
available = [1, 0]
alloc = [[0,1],[2,0],[3,0]]
need = [[2,0],[1,0],[0,2]]
print(safe_state(available, alloc, need))  # prints True if the state is safe, otherwise False

