#include <stdio.h>
int main(){
    int available[2] = {0,1};
    int alloc[3][2] = {{0,1},{2,0},{1,0}};
    int max[3][2] = {{2,1},{3,1},{3,2}};
    int request[2] = {1,0};
    int need[3][2];
    for(int i=0;i<3;i++) for(int j=0;j<2;j++) need[i][j]=max[i][j]-alloc[i][j];
    // check request <= need for P1
    if(request[0]>need[1][0]||request[1]>need[1][1]){printf("Deny\n"); return 0;}
    // pretend allocation
    int avail2[2] = {available[0]-request[0], available[1]-request[1]};
    int alloc2[3][2];
    for(int i=0;i<3;i++) for(int j=0;j<2;j++) alloc2[i][j]=alloc[i][j];
    alloc2[1][0]+=request[0]; alloc2[1][1]+=request[1];
    int need2[3][2];
    for(int i=0;i<3;i++) for(int j=0;j<2;j++) need2[i][j]=need[i][j];
    need2[1][0]-=request[0]; need2[1][1]-=request[1];
    // safety test
    int work[2] = {avail2[0], avail2[1]};
    int finish[3] = {0,0,0};
    int changed;
    do{
        changed=0;
        for(int i=0;i<3;i++) if(!finish[i]){
            int can=1;
            for(int j=0;j<2;j++) if(need2[i][j]>work[j]){can=0; break;}
            if(can){
                for(int j=0;j<2;j++) work[j]+=alloc2[i][j];
                finish[i]=1; changed=1;
            }
        }
    }while(changed);
    int safe=1; for(int i=0;i<3;i++) if(!finish[i]) safe=0;
    printf(safe?"Grant\n":"Deny\n");
    return 0;
}
